"""Versioned agent obligations, visible only within the current role scope."""
import json

POLICY_VERSION = '1.1.0'
RULES_ID = 'robot-required-rules'
UPLOAD_ID = 'robot-worksheet-upload'
TEX_ID = 'robot-tex-build'
CATEGORY = 'Обязательные инструкции для роботов'


def mandatory_instructions(user, *, read_only=False):
    entries = [dict(section_id=RULES_ID, title='Обязательные правила для роботов', version=POLICY_VERSION,
                    required=True, applies_when='any-api-workflow', can_execute=True,
                    url=f'/api/v1/documentation/{RULES_ID}?audience=robot')]
    if {'teacher','admin'} & set(user.roles):
        entries.append(dict(section_id=UPLOAD_ID, title='Загрузка листка: обязательный протокол', version=POLICY_VERSION,
            required=True, applies_when='worksheet-upload', can_execute=not read_only,
            url=f'/api/v1/documentation/{UPLOAD_ID}?audience=robot'))
        entries.append(dict(section_id=TEX_ID,title='Обязательная сборка и согласование TeX',version=POLICY_VERSION,
            required=True,applies_when='worksheet-upload',can_execute=True,
            url=f'/api/v1/documentation/{TEX_ID}?audience=robot'))
    return entries


def step(title, items, **extra):
    return dict(title=title, steps=items, api_steps=list(items), **extra)


def workflow_sections(user, *, read_only=False):
    entries=mandatory_instructions(user,read_only=read_only)
    rules=dict(id=RULES_ID, category=CATEGORY, title=entries[0]['title'],
        summary='MUST: прочитать обязательные инструкции до работы с API и соблюдать подтверждения пользователя.',
        keywords='robot бот агент MUST MUST_NOT required обязательные инструкции протокол вопросы подтверждение', links=[],
        blocks=[
            dict(title='Статус и область действия',paragraphs=[
                f'Версия обязательного контракта: {POLICY_VERSION}. MUST означает «обязан», MUST NOT — «запрещено». Это правила работы агента с Plusfolio, а не необязательные советы.',
                'После авторизации перед каждым новым сценарием робот MUST получить GET /api/v1/documentation?audience=robot, прочитать mandatory_instructions и все инструкции, применимые к сценарию. Нельзя считать прежний кэш актуальным после изменения версии или прав.',
                'Перед загрузкой листка робот MUST полностью прочитать robot-worksheet-upload, если этот раздел доступен. Если инструкция для запрошенной операции недоступна или can_execute=false, робот MUST остановиться перед записью и сообщить причину.',
                'Контракт не расширяет права аккаунта и не отменяет ограничения среды. Сервер проверяет права и данные; соблюдение вопросов и достоверность ответов остаются обязанностью агента.']),
            dict(title='Обязательные правила диалога',bullets=[
                'Все уточнения и согласования MUST оформляться дополнительными вопросами пользователю. При наличии инструмента дополнительных вопросов MUST использовать его; если такого инструмента нет — задать отдельный явный вопрос и ждать ответа.',
                'Робот MUST NOT подменять вопрос сообщением о ходе работы, собственным предположением, выбранным по умолчанию вариантом или молчанием пользователя. Закрытый вопрос без ответа, тайм-аут и истечение времени не означают согласие.',
                'Каждый вопрос MUST указывать объект: номер задачи во входном листке, её краткое условие и конкретное решение, которое требуется от пользователя. При загрузке листка можно объединять только уточнения одной текущей задачи. Разные задачи MUST согласовываться отдельно и последовательно в порядке листка, а не одной общей формой.',
                'Пока обязательный ответ не получен, зависимую запись в API выполнять MUST NOT. Разрешены независимое чтение, поиск и подготовка предложений.',
                'Робот MUST сохранять реальные ответы в своём журнале работы и возобновлять процесс с незавершённого шага. Нельзя придумывать подтверждения или повторно спрашивать уже полученный точный ответ без изменения данных.']),
            dict(title='Обязательные правила API и отчёта',bullets=[
                'Робот MUST использовать только методы и область данных, доступные текущему аккаунту и токену. Токен read_only не разрешает создание задач, тем, тегов и листков; POST поиска остаётся операцией чтения.',
                'Темы и теги может создавать только администратор. Запрос пользователя создать тему или тег не повышает права бота. Робот MUST NOT выдавать себе роль, создавать администратора или обходить ограничения.',
                'Робот MUST брать UUID и числовые ID из ответов API. Публичные P-/W-/TOP-/TAG-ID нужны для показа и поиска, а не для подстановки вместо внутренних ID.',
                'После каждого успешного создания робот MUST немедленно записать и сообщить ID. В итоговом ответе MUST перечислить новые и использованные задачи, их ID и ID листка.',
                'Робот MUST NOT автоматически повторять POST создания после тайм-аута или неизвестного результата. Сначала перечитать данные, проверить журнал и задать вопрос о неоднозначном результате.',
                'Робот MUST NOT сообщать об успешном создании без успешного ответа и сохранённых ID. При остановке MUST выдать честный частичный результат с уже известными ID.']),
        ])
    sections=[rules]
    if len(entries)>1:
        sections.append(upload_section(admin='admin' in user.roles))
        sections.append(tex_build_section())
    for section, entry in zip(sections, entries):
        section.update(required_for_robots=True,instruction_version=POLICY_VERSION,
                       applies_when=entry['applies_when'],can_execute=entry['can_execute'])
    return sections


def upload_section(*, admin):
    taxonomy = ([
        'Только после явного запроса пользователя создать тему уточните её точное название и родительский узел дополнительным вопросом. Проверьте существующее дерево, затем POST /api/v1/topics с name и parent_id. Сохраните id и public_id из HTTP 201; обновите дерево через GET /api/v1/topics.',
        'Родитель темы MUST быть действующим обычным узлом, не «Прочее». Системное «Прочее» создаётся автоматически; робот MUST NOT создавать его вручную. Одинаковые названия под разными родителями нельзя путать.',
        'Только после явного запроса создать тег уточните название и справочник: problem или worksheet. POST /api/v1/tags с kind и name возвращает HTTP 201 и список тегов; найдите запись по точным kind+name и сохраните её числовой id и public_id. Не предполагайте, что ответ — один объект тега.',
    ] if admin else [
        'У текущей роли нет права создавать темы и теги. При таком запросе робот MUST задать дополнительный вопрос: выбрать существующий вариант либо остановиться до действий администратора.',
        'Робот MUST NOT вызывать создание тем/тегов, повышать себе права или молча заменять запрошенную тему на «Прочее». После действий администратора перечитайте справочник и вновь согласуйте выбор.',
    ])
