def tex_build_section():
    from pathlib import Path
    guide=(Path(__file__).resolve().parents[2]/'docs'/'tex-preflight.md').read_text()
    blocks=[dict(title='Обязательная проверка перед публикацией',paragraphs=[
        'Робот MUST полностью воспроизвести процесс сборки сервиса перед отправкой задачи и итогового листка, проверить все страницы и получить согласование PDF. Другая версия TeX, похожая преамбула или только успешный код возврата не подходят.',
        'Получить актуальный contract_id и архив через API. Пакет использует точные project_for, fragment, flatten, render_pdf и tex_worker сервиса. Локальный предпросмотр не создаёт записей в БД.'])]
    title='Процесс сборки';paragraphs=[];code=None;language=''
    def flush():
        nonlocal paragraphs
        if paragraphs:blocks.append(dict(title=title,paragraphs=paragraphs));paragraphs=[]
    for line in guide.splitlines():
        if line.startswith('# '):continue
        if line.startswith('## '):flush();title=line[3:];continue
        if line.startswith('```'):
            if code is None:flush();code=[];language=line[3:]
            else:blocks.append(dict(title=title+' — команда/формат',code={'language':language,'content':'\n'.join(code)}));code=None
        elif code is not None:code.append(line)
        elif line.strip():paragraphs.append(line.replace('`','').replace('**','').removeprefix('- '))
    flush()
    return dict(id=TEX_ID,category=CATEGORY,title='Обязательная сборка и согласование TeX',
        summary='MUST: точный пакет сервиса, оба PDF, просмотр всех страниц и согласование до загрузки.',
        keywords='tectonic TeX TikZ сборка вёрстка верстка PDF preview preflight contract_id',links=[],blocks=blocks)
